// sequences.ts
//
// Small helpers for building lists of numbers. These are used by reporting
// and formatting code elsewhere in the application.
//
// Conventions shared by every helper in this module:
// - Functions that take a count `n` return a new array with exactly `n` items.
// - `n` is always a non-negative integer. Callers validate input before
//   calling these helpers, so the helpers do not check it again.
// - A count of 0 returns an empty array.
// - Helpers never mutate arrays that are passed to them.
// - Helpers are plain functions with no shared state, so each call returns
//   a fresh array that the caller is free to modify.

/**
 * Returns the integers from `start` (inclusive) to `end` (exclusive).
 * Returns an empty array when `end` is less than or equal to `start`.
 *
 * Example: range(2, 6) returns [2, 3, 4, 5].
 */
export function range(start: number, end: number): number[] {
  const result: number[] = [];
  for (let value = start; value < end; value++) {
    result.push(value);
  }
  return result;
}

/**
 * Returns the integers counting down from `n` to 1.
 *
 * Example: countdown(4) returns [4, 3, 2, 1].
 */
export function countdown(n: number): number[] {
  const result: number[] = [];
  for (let value = n; value >= 1; value--) {
    result.push(value);
  }
  return result;
}

/**
 * Returns the first `n` even numbers, starting at 0.
 *
 * Example: evens(4) returns [0, 2, 4, 6].
 */
export function evens(n: number): number[] {
  const result: number[] = [];
  for (let index = 0; index < n; index++) {
    result.push(index * 2);
  }
  return result;
}

/**
 * Returns the first `n` odd numbers, starting at 1.
 *
 * Example: odds(4) returns [1, 3, 5, 7].
 */
export function odds(n: number): number[] {
  const result: number[] = [];
  for (let index = 0; index < n; index++) {
    result.push(index * 2 + 1);
  }
  return result;
}

/**
 * Returns the squares of the first `n` positive integers.
 *
 * Example: squares(4) returns [1, 4, 9, 16].
 */
export function squares(n: number): number[] {
  const result: number[] = [];
  for (let value = 1; value <= n; value++) {
    result.push(value * value);
  }
  return result;
}

/**
 * Returns the cubes of the first `n` positive integers.
 *
 * Example: cubes(4) returns [1, 8, 27, 64].
 */
export function cubes(n: number): number[] {
  const result: number[] = [];
  for (let value = 1; value <= n; value++) {
    result.push(value * value * value);
  }
  return result;
}

/**
 * Returns the first `n` triangular numbers. The k-th triangular number is
 * the sum of the integers from 1 to k.
 *
 * Example: triangularNumbers(5) returns [1, 3, 6, 10, 15].
 */
export function triangularNumbers(n: number): number[] {
  const result: number[] = [];
  let total = 0;
  for (let value = 1; value <= n; value++) {
    total += value;
    result.push(total);
  }
  return result;
}

/**
 * Returns the first `n` powers of two, starting at 2^0.
 *
 * Example: powersOfTwo(5) returns [1, 2, 4, 8, 16].
 */
export function powersOfTwo(n: number): number[] {
  const result: number[] = [];
  let power = 1;
  for (let index = 0; index < n; index++) {
    result.push(power);
    power *= 2;
  }
  return result;
}

/**
 * Returns the first `n` positive multiples of `step`.
 *
 * Example: multiplesOf(3, 4) returns [3, 6, 9, 12].
 */
export function multiplesOf(step: number, n: number): number[] {
  const result: number[] = [];
  for (let index = 1; index <= n; index++) {
    result.push(step * index);
  }
  return result;
}

/**
 * Returns an array containing `value` repeated `n` times.
 *
 * Example: repeatValue(7, 3) returns [7, 7, 7].
 */
export function repeatValue(value: number, n: number): number[] {
  const result: number[] = [];
  for (let index = 0; index < n; index++) {
    result.push(value);
  }
  return result;
}

/**
 * Returns the sum of all numbers in `values`. The sum of an empty array is 0.
 *
 * Example: sum([2, 3, 5]) returns 10.
 */
export function sum(values: number[]): number {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

/**
 * Returns the running totals of `values`: each item is the sum of every
 * value up to and including that position. Returns an empty array for an
 * empty input.
 *
 * Example: runningTotals([2, 3, 5]) returns [2, 5, 10].
 */
export function runningTotals(values: number[]): number[] {
  const result: number[] = [];
  let total = 0;
  for (const value of values) {
    total += value;
    result.push(total);
  }
  return result;
}

/**
 * Returns the differences between neighbouring values: each item is the
 * next value minus the current one. Arrays with fewer than two values
 * return an empty array.
 *
 * Example: differences([1, 4, 9, 16]) returns [3, 5, 7].
 */
export function differences(values: number[]): number[] {
  const result: number[] = [];
  for (let index = 1; index < values.length; index++) {
    result.push(values[index] - values[index - 1]);
  }
  return result;
}

/**
 * Returns a new array with every value in `values` multiplied by `factor`.
 *
 * Example: scaled([1, 2, 3], 10) returns [10, 20, 30].
 */
export function scaled(values: number[], factor: number): number[] {
  const result: number[] = [];
  for (const value of values) {
    result.push(value * factor);
  }
  return result;
}

/**
 * Returns a new array with the values of `values` in reverse order.
 *
 * Example: reversed([1, 2, 3]) returns [3, 2, 1].
 */
export function reversed(values: number[]): number[] {
  const result: number[] = [];
  for (let index = values.length - 1; index >= 0; index--) {
    result.push(values[index]);
  }
  return result;
}

/**
 * Returns every `step`-th value of `values`, starting with the first value.
 * `step` is always a positive integer.
 *
 * Example: everyNth([5, 6, 7, 8, 9], 2) returns [5, 7, 9].
 */
export function everyNth(values: number[], step: number): number[] {
  const result: number[] = [];
  for (let index = 0; index < values.length; index += step) {
    result.push(values[index]);
  }
  return result;
}

/**
 * Returns the largest number in `values`, or undefined for an empty array.
 *
 * Example: largest([4, 9, 2]) returns 9.
 */
export function largest(values: number[]): number | undefined {
  let best: number | undefined;
  for (const value of values) {
    if (best === undefined || value > best) {
      best = value;
    }
  }
  return best;
}

/**
 * Returns the smallest number in `values`, or undefined for an empty array.
 *
 * Example: smallest([4, 9, 2]) returns 2.
 */
export function smallest(values: number[]): number | undefined {
  let best: number | undefined;
  for (const value of values) {
    if (best === undefined || value < best) {
      best = value;
    }
  }
  return best;
}
